            </strong>
        </div>
    `;

    // Individual question results
    ['q1', 'q2', 'q3'].forEach(question => {
        const result = results[question];
        const label = questionLabels[question];
        const status = result.isCorrect ? '✓ Correct' : '✗ Incorrect';
        const statusColor = result.isCorrect ? '#10b981' : '#ef4444';

        html += `
            <div class="result-item" style="border-color: ${statusColor}; background: rgba(${result.isCorrect ? '16, 185, 129' : '239, 68, 68'}, 0.05);">
