+const answerKey = {
+    q1: ['python', 'javascript'],
+    q2: ['python', 'java', 'rust'],
+    q3: ['cpp', 'c']
+};
+
+const questionLabels = {
+    q1: 'Dynamically typed languages',
+    q2: 'Backend web development languages',
+    q3: 'Languages that compile to machine code'
+};
+
+document.getElementById('quizForm').addEventListener('submit', function(e) {
+    e.preventDefault();
+    
+    const userAnswers = {
+        q1: getSelectedAnswers('q1'),
+        q2: getSelectedAnswers('q2'),
+        q3: getSelectedAnswers('q3')
+    };
+    
+    const results = calculateResults(userAnswers);
+    displayResults(results, userAnswers);
+});
+
+function getSelectedAnswers(questionName) {
+    const checkboxes = document.querySelectorAll(`input[name="${questionName}"]:checked`);
+    return Array.from(checkboxes).map(cb => cb.value);
+}
+
+function calculateResults(userAnswers) {
+    const results = {};
+    let totalCorrect = 0;
+
+    Object.keys(answerKey).forEach(question => {
+        const correct = answerKey[question];
+        const userAnswer = userAnswers[question];
+        
+        const isCorrect = 
+            correct.length === userAnswer.length && 
+            correct.every(answer => userAnswer.includes(answer));
+        
+        results[question] = {
+            isCorrect,
+            correct,
+            user: userAnswer
+        };
+        
+        if (isCorrect) {
+            totalCorrect++;
+        }
+    });
+
+    results.totalCorrect = totalCorrect;
+    results.percentage = Math.round((totalCorrect / 3) * 100);
+    
+    return results;
+}
+
+function displayResults(results, userAnswers) {
+    const quizForm = document.getElementById('quizForm');
+    const resultDiv = document.getElementById('result');
+    const resultContent = document.getElementById('resultContent');
+    
+    let html = '';
+    
+    // Overall score
+    html += `
+        <div class="result-item" style="border-color: ${results.totalCorrect === 3 ? '#10b981' : '#f59e0b'}; background: rgba(${results.totalCorrect === 3 ? '16, 185, 129' : '245, 158, 11'}, 0.05);">
+            <strong style="color: ${results.totalCorrect === 3 ? '#10b981' : '#f59e0b'};">
+                Score: ${results.totalCorrect} out of 3 (${results.percentage}%)
+            </strong>
+        </div>
+    `;
+    
+    // Individual question results
+    ['q1', 'q2', 'q3'].forEach(question => {
+        const result = results[question];
+        const label = questionLabels[question];
+        const status = result.isCorrect ? '✓ Correct' : '✗ Incorrect';
+        const statusColor = result.isCorrect ? '#10b981' : '#ef4444';
+        
+        html += `
+            <div class="result-item" style="border-color: ${statusColor}; background: rgba(${result.isCorrect ? '16, 185, 129' : '239, 68, 68'}, 0.05);">
+                <div style="color: ${statusColor}; font-weight: bold; margin-bottom: 8px;">${status}</div>
+                <div style="color: var(--color-text-secondary); margin-bottom: 8px;">
+                    <strong>Question:</strong> ${label}
+                </div>
+                <div style="color: var(--color-text-secondary); margin-bottom: 8px;">
+                    <strong>Correct answers:</strong> ${result.correct.join(', ')}
+                </div>
+                <div style="color: var(--color-text-secondary);">
+                    <strong>Your answers:</strong> ${result.user.length > 0 ? result.user.join(', ') : '(none selected)'}
+                </div>
+            </div>
+        `;
+    });
+    
+    resultContent.innerHTML = html;
+    quizForm.style.display = 'none';
+    resultDiv.style.display = 'block';
+}
+
')
